import{_ as o,o as t,c as a,a3 as i}from"./chunks/framework.WFmvnizL.js";const g=JSON.parse('{"title":"Login FAQ","description":"Official Nezha Monitoring V2 documentation for Login FAQ. Learn the relevant features, configuration steps, operational boundaries, use cases, and troubleshooting guidance for Dashboard and Agent.","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"en_US/guide/loginq.md","filePath":"en_US/guide/loginq.md","lastUpdated":1792674226000}'),n={name:"en_US/guide/loginq.md"};function r(s,e,d,l,c,h){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="login-faq" tabindex="-1">Login FAQ <a class="header-anchor" href="#login-faq" aria-label="Permalink to &quot;Login FAQ&quot;">​</a></h1><p>The current V2 Dashboard uses local account login and supports binding local accounts to third-party OAuth2 accounts. Legacy GitHub OAuth login issues no longer apply to the current login flow.</p><h2 id="forgot-administrator-password" tabindex="-1">Forgot Administrator Password <a class="header-anchor" href="#forgot-administrator-password" aria-label="Permalink to &quot;Forgot Administrator Password&quot;">​</a></h2><p>See <a href="/en_US/guide/q13.html">Initialize User Password</a>. After resetting it, log in to the admin frontend and change it to a new strong password as soon as possible.</p><h2 id="oauth2-login-failed" tabindex="-1">OAuth2 Login Failed <a class="header-anchor" href="#oauth2-login-failed" aria-label="Permalink to &quot;OAuth2 Login Failed&quot;">​</a></h2><p>Check the following first:</p><ol><li>The <code>oauth2</code> field in the Dashboard configuration uses the new structure. See <a href="/en_US/guide/q14.html">Setting Up OAuth 2.0 Binding</a>.</li><li>The Callback URL on the third-party platform is <code>https://your-dashboard-domain/api/v1/oauth2/callback</code>.</li><li>You have already logged in with a local account and completed OAuth2 binding on the profile page.</li></ol><p>If no binding relationship exists yet, OAuth2 cannot directly log in to a local account.</p><h2 id="session-lost-after-switching-networks" tabindex="-1">Session Lost After Switching Networks <a class="header-anchor" href="#session-lost-after-switching-networks" aria-label="Permalink to &quot;Session Lost After Switching Networks&quot;">​</a></h2><p>Dashboard binds browser JWT sessions to the client IP identified at login by default. Switching Wi-Fi, mobile networks, VPNs, or proxy exits may require signing in again. This does not necessarily mean an incorrect password or a blocked account.</p><p>First verify the <a href="/en_US/guide/q12.html">Frontend Real IP Request Header</a>, so the proxy does not misidentify visitors as a shared or unstable address. If sessions must survive IP changes, set <a href="/en_US/configuration/dashboard.html#allow-jwt-ip-change"><code>allow_jwt_ip_change: true</code></a>. This relaxes session protection; the default remains <code>false</code>, and the current admin frontend has no switch for it.</p><p>The default user frontend homepage shows a login prompt with a <code>/dashboard</code> link when a guest API returns <code>ApiErrorUnauthorized</code>, rather than reporting backend unavailability. Sign in first when <code>force_auth</code> is enabled; this prompt alone does not indicate offline Agents.</p><h2 id="login-endpoint-is-frequently-tried-or-incorrectly-blocked" tabindex="-1">Login Endpoint Is Frequently Tried or Incorrectly Blocked <a class="header-anchor" href="#login-endpoint-is-frequently-tried-or-incorrectly-blocked" aria-label="Permalink to &quot;Login Endpoint Is Frequently Tried or Incorrectly Blocked&quot;">​</a></h2><p>V2 includes a Web Application Firewall to limit login brute-force attempts. If Dashboard is deployed behind a reverse proxy or CDN, configure the <a href="/en_US/guide/q12.html">Frontend Real IP Request Header</a> correctly; otherwise, Dashboard may misidentify visitor IPs and block incorrectly.</p><p>If an IP has already been blocked by mistake, use an administrator account to remove the corresponding block record under <strong>System Settings → Web Application Firewall</strong>.</p>',15)])])}const p=o(n,[["render",r]]);export{g as __pageData,p as default};
